class Address { public required string City { get; init; } }
class Person {
    public required string Name;
    public required Address Address { get; init; }
    public required int Age { get; set; } = 1;
    public string Label => Name + ":" + Address.City + ":" + Age;
}
Person Make() => new Person { Age = 30, Name = "Ada", Address = new Address { City = "London" } };
void Main() { var p = Make(); Print(p.Label); p.Age++; Print(p.Label); }
